public record StatusUpdate(DateTime Timestamp, string Description);

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTime EstimatedDelivery,
    List<StatusUpdate> Updates);

public abstract class ShipmentService
{
    public abstract Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_33280ce4d7ff4d69bca136fddcc81e40.Client.Services;

namespace sv_33280ce4d7ff4d69bca136fddcc81e40.Services;

public class ServerShipmentService : ShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new()
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Chicago, IL",
            new DateTime(2026, 6, 15),
            new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 8, 9, 0, 0), "Package picked up"),
                new(new DateTime(2026, 6, 9, 14, 30, 0), "Arrived at sorting facility"),
                new(new DateTime(2026, 6, 10, 8, 15, 0), "In transit to destination hub"),
            }),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "Austin, TX",
            new DateTime(2026, 6, 10),
            new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 6, 10, 0, 0), "Package picked up"),
                new(new DateTime(2026, 6, 7, 16, 0, 0), "Arrived at regional hub"),
                new(new DateTime(2026, 6, 9, 11, 0, 0), "Out for delivery"),
                new(new DateTime(2026, 6, 9, 15, 22, 0), "Delivered — signed by recipient"),
            }),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Seattle, WA",
            new DateTime(2026, 6, 18),
            new List<StatusUpdate>
            {
                new(new DateTime(2026, 6, 11, 7, 0, 0), "Order confirmed, awaiting pickup"),
            }),
    };

    public override async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

using System.Net.Http.Json;

namespace sv_33280ce4d7ff4d69bca136fddcc81e40.Client.Services;

public class ClientShipmentService(HttpClient http) : ShipmentService
{
    public override async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var result = await http.GetFromJsonAsync<ShipmentDetails>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);
        return result ?? throw new InvalidOperationException("Received null response from API.");
    }
}

