@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@implements IAsyncDisposable
@inject ShipmentService ShipmentService
@inject ILogger<Shipment> Logger

@if (error is not null)
{
    <div class="alert alert-danger">
